<div class="d-flex flex-wrap justify-content-between align-items-start gap-2 mb-3"><div><h1><?= e($seed['name']) ?></h1><p class="lead mb-0">Seed # <?= e($seed['seed_number']) ?> <?= $seed['variety'] ? '· '.e($seed['variety']) : '' ?></p></div><div class="no-print"><a class="btn btn-success" href="<?= e(url('seeds/'.$seed['id'].'/edit')) ?>">Edit</a><form method="post" action="<?= e(url('seeds/'.$seed['id'].'/duplicate')) ?>" class="d-inline"><?= csrf_field() ?><button class="btn btn-outline-secondary">Duplicate</button></form><form method="post" action="<?= e(url('seeds/'.$seed['id'].'/delete')) ?>" class="d-inline" data-confirm="Delete this seed? Seed numbers are never auto-renumbered."><?= csrf_field() ?><button class="btn btn-outline-danger">Delete</button></form></div></div>
<div class="row g-3"><div class="col-lg-8"><div class="card"><div class="card-body"><h2 class="h5">Planting & Growing</h2><dl class="row"><dt class="col-sm-4">Category</dt><dd class="col-sm-8"><?= e($seed['category_name']) ?></dd><dt class="col-sm-4">Plant Family</dt><dd class="col-sm-8"><?= e($seed['family_name']) ?></dd><dt class="col-sm-4">Plant Type</dt><dd class="col-sm-8"><?= e($seed['plant_type']) ?></dd><dt class="col-sm-4">Method</dt><dd class="col-sm-8"><?= e($seed['planting_method']) ?></dd><dt class="col-sm-4">Planting Window</dt><dd class="col-sm-8"><?= e(date_label($seed['planting_start_month'],$seed['planting_start_day'])) ?> – <?= e(date_label($seed['planting_end_month'],$seed['planting_end_day'])) ?></dd><dt class="col-sm-4">Indoor Start</dt><dd class="col-sm-8"><?= e($seed['indoor_start_weeks_before_frost']) ?> weeks before frost</dd><dt class="col-sm-4">Transplant Timing</dt><dd class="col-sm-8"><?= e($seed['transplant_weeks_after_frost']) ?> weeks after frost</dd><dt class="col-sm-4">Succession</dt><dd class="col-sm-8"><?= e($seed['succession_days']) ?> days</dd><dt class="col-sm-4">Germination</dt><dd class="col-sm-8"><?= e($seed['days_to_germination_min']) ?>–<?= e($seed['days_to_germination_max']) ?> days</dd><dt class="col-sm-4">Maturity</dt><dd class="col-sm-8"><?= e($seed['days_to_maturity']) ?> days</dd><dt class="col-sm-4">Sun / Water / Soil</dt><dd class="col-sm-8"><?= e($seed['sun_requirements']) ?> · <?= e($seed['water_requirements']) ?> · <?= e($seed['soil_requirements']) ?></dd><dt class="col-sm-4">Spacing / Depth / Height</dt><dd class="col-sm-8"><?= e($seed['spacing']) ?> · <?= e($seed['sowing_depth']) ?> · <?= e($seed['plant_height']) ?></dd></dl><h3 class="h6">Flags</h3><p><?php foreach(['container_friendly'=>'Container','pollinator_friendly'=>'Pollinator','medicinal'=>'Medicinal','perennial'=>'Perennial','frost_tolerant'=>'Frost tolerant','heat_tolerant'=>'Heat tolerant','trellis_needed'=>'Trellis needed'] as $k=>$v): if($seed[$k]): ?><span class="badge bg-success seed-badge"><?= e($v) ?></span> <?php endif; endforeach; ?></p></div></div></div><div class="col-lg-4"><div class="card mb-3"><div class="card-body"><h2 class="h5">Inventory</h2><p><strong>Status:</strong> <?= e($seed['status_name']) ?></p><p><strong>Source:</strong> <?= e($seed['seed_source']) ?></p><p><strong>Packet Year:</strong> <?= e($seed['packet_year']) ?></p><p><strong>Purchase Date:</strong> <?= e($seed['purchase_date']) ?></p><p><strong>Expiration Year:</strong> <?= e($seed['expiration_year']) ?></p><p><strong>Quantity:</strong> <?= e($seed['quantity']) ?></p><p><strong>Location:</strong> <?= e(trim(($seed['storage_box']??'').' / '.($seed['container']??'').' / '.($seed['envelope']??'').' / '.($seed['row_label']??'').' / '.($seed['slot']??''), ' /')) ?></p><p><strong>Storage Notes:</strong> <?= e($seed['location_notes']) ?></p></div></div><div class="card"><div class="card-body"><h2 class="h5">Uses</h2><?php foreach($uses as $u): ?><span class="badge bg-secondary"><?= e($u['name']) ?></span> <?php endforeach; ?></div></div></div><div class="col-lg-12"><div class="card"><div class="card-body"><h2 class="h5">Companion Relationships</h2><div class="table-responsive"><table class="table"><thead><tr><th>Type</th><th>Plant</th><th>Notes</th></tr></thead><tbody><?php foreach($companions as $c): ?><tr><td><?= e($c['relationship_type']) ?></td><td><?= e($c['name']) ?></td><td><?= e($c['notes']) ?></td></tr><?php endforeach; if(!$companions): ?><tr><td colspan="3" class="text-muted">No companion relationships recorded.</td></tr><?php endif; ?></tbody></table></div><h2 class="h5">Notes</h2><p><?= nl2br(e($seed['notes'])) ?></p><h2 class="h5">Recent History</h2><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Date</th><th>Action</th><th>User</th></tr></thead><tbody><?php foreach($history as $h): ?><tr><td><?= e($h['created_at']) ?></td><td><?= e($h['action']) ?></td><td><?= e($h['user_name']) ?></td></tr><?php endforeach; if(!$history): ?><tr><td colspan="3" class="text-muted">No history recorded.</td></tr><?php endif; ?></tbody></table></div></div></div></div></div>
